import { expect, test, type Page } from "@playwright/test";
import { fetchSeats, login, mapCanvas, restoreSeat } from "./helpers";

/**
 * 좌석 사각형의 도면 좌표. 화면 좌표는 편집 모드에서 도구 줄이 늘어나며 함께
 * 움직이므로, 레이아웃과 무관한 이 값으로 이동을 확인한다.
 */
const seatAt = (page: Page, name: string) =>
  page.evaluate((label) => {
    const svg = document.querySelector("svg[aria-label*='좌석 배치도']")!;
    const group = Array.from(svg.querySelectorAll("g")).find(
      (node) => node.querySelector("text")?.textContent === label,
    )!;
    // 선택된 좌석은 앞에 강조 테두리가 하나 더 붙는다. 좌석 본체는 마지막 것.
    const rects = Array.from(group.querySelectorAll("rect"));
    const rect = rects[rects.length - 1];
    return {
      x: Number(rect.getAttribute("x")),
      y: Number(rect.getAttribute("y")),
    };
  }, name);

test.describe("좌석 배치 편집", () => {
  // 이 검증은 좌석 위치를 실제로 바꾼다. 되돌리지 않으면 반복 실행할수록 좌석이
  // 한쪽으로 밀려 서로 겹치고, 다음 실행이 엉뚱한 이유로 깨진다.
  let origin: Array<{ id: string; x: number; y: number }> = [];

  test.beforeEach(async ({ page }) => {
    await login(page);
    origin = (await fetchSeats(page)).map((seat) => ({
      id: seat.id,
      x: seat.x,
      y: seat.y,
    }));
    await mapCanvas(page).waitFor();
    await page.getByRole("button", { name: /배치 편집/ }).click();
  });

  test.afterEach(async ({ page }) => {
    const now = await fetchSeats(page);
    for (const seat of now) {
      const was = origin.find((item) => item.id === seat.id);
      if (was && (was.x !== seat.x || was.y !== seat.y)) {
        await restoreSeat(page, seat.id, was);
      }
    }
  });

  test("방향키로 옮긴 자리가 서버에 남는다", async ({ page }) => {
    const before = await seatAt(page, "김개발");
    await select(page, "김개발");
    await page.keyboard.press("ArrowRight");
    await expect
      .poll(async () => (await seatAt(page, "김개발")).x)
      .toBeGreaterThan(before.x);
    const moved = await seatAt(page, "김개발");

    // 화면에서만 움직이고 서버에 남지 않으면 다음 접속에서 제자리로 돌아간다.
    await page.reload();
    await mapCanvas(page).waitFor();
    await expect
      .poll(async () => (await seatAt(page, "김개발")).x)
      .toBeCloseTo(moved.x, 1);
  });

  test("실행 취소로 옮기기 전 자리로 돌아간다", async ({ page }) => {
    const before = await seatAt(page, "이코딩");
    const savedBefore = await saved(page, "이코딩");
    await select(page, "이코딩");
    await page.keyboard.press("ArrowDown");
    await expect
      .poll(async () => (await seatAt(page, "이코딩")).y)
      .toBeGreaterThan(before.y);
    // 저장이 끝나기 전에 실행 취소를 누르면 두 요청이 앞뒤로 엇갈린다. 서버가
    // 옮긴 자리를 받아들인 것을 확인한 뒤에 되돌린다. 서버는 비율 좌표를 쓰므로
    // 화면 좌표와 섞어 비교하지 않는다.
    await expect
      .poll(async () => saved(page, "이코딩"))
      .toBeGreaterThan(savedBefore);

    await page.keyboard.press("ControlOrMeta+z");
    await expect
      .poll(async () => (await seatAt(page, "이코딩")).y)
      .toBeCloseTo(before.y, 1);

    await page.reload();
    await mapCanvas(page).waitFor();
    expect((await seatAt(page, "이코딩")).y).toBeCloseTo(before.y, 1);
  });

  test("끌어서 옮겨도 자리가 바뀐다", async ({ page }) => {
    const before = await seatAt(page, "박서버");
    const seat = mapCanvas(page)
      .locator("g")
      .filter({ hasText: "박서버" })
      .first();
    const box = (await seat.boundingBox())!;
    // 좌석이 겹치지 않도록 도면 아래쪽 빈 곳으로 내린다.
    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    await page.mouse.down();
    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2 + 120, {
      steps: 12,
    });
    await page.mouse.up();
    await expect
      .poll(async () => (await seatAt(page, "박서버")).y)
      .toBeGreaterThan(before.y);
    const moved = await seatAt(page, "박서버");

    await page.reload();
    await mapCanvas(page).waitFor();
    await expect
      .poll(async () => (await seatAt(page, "박서버")).y)
      .toBeCloseTo(moved.y, 1);
  });
});

/** 서버에 저장된 좌석의 세로 위치(비율 좌표). */
const saved = async (page: Page, name: string) => {
  const seat = (await fetchSeats(page)).find(
    (item) => item.employeeName === name,
  );
  return seat ? seat.y : -1;
};

/** 좌석을 눌러 선택한다. 방향키 미세 이동은 선택된 좌석에만 걸린다. */
const select = async (page: Page, name: string) => {
  await mapCanvas(page).locator("g").filter({ hasText: name }).first().click();
  await expect(page.getByText(/1개 선택|개 선택/)).toBeVisible();
};
import { expect, type Page } from "@playwright/test";

/** 시드가 만드는 층. 검증은 이 층의 좌석을 기준으로 한다. */
export const SEED_FLOOR = "3층";

const USERNAME = process.env.E2E_USERNAME ?? "admin";
const PASSWORD = process.env.E2E_PASSWORD ?? "e2e-verify-pass-123";

export const login = async (page: Page) => {
  await page.goto("/login");
  await page.fill('input[autocomplete="username"]', USERNAME);
  await page.fill('input[autocomplete="current-password"]', PASSWORD);
  await page.click('button[type="submit"]');
  await page.waitForURL((url) => !url.pathname.startsWith("/login"));
};

export const mapCanvas = (page: Page) =>
  page.locator("svg[aria-label*='좌석 배치도']");

export const seatLabels = async (page: Page) =>
  mapCanvas(page).locator("text").allTextContents();

/**
 * 좌석 목록을 API로 읽는다. 화면을 거치지 않으므로 검증 전후 상태를 확인하고
 * 되돌리는 데 쓴다.
 */
export const fetchSeats = async (page: Page) => {
  const maps = await (await page.request.get("/api/v1/floor-maps")).json();
  // 도면 버전은 여러 개이고 층도 여러 개일 수 있다. 검증이 다루는 것은 시드가
  // 만든 층의 게시된 버전이므로, 그 층을 이름으로 집어 고른다. 그러지 않으면
  // 나중에 추가된 다른 층의 좌석을 읽어 "김개발이 없다"는 식으로 깨진다.
  type MapItem = { id: string; active?: boolean; floorName?: string };
  const items = maps.items as MapItem[];
  const map =
    items.find((item) => item.active && item.floorName === SEED_FLOOR) ??
    items.find((item) => item.active) ??
    items[0];
  const mapId = map.id;
  const seats = await (
    await page.request.get(`/api/v1/seats?floorMapId=${mapId}`)
  ).json();
  return seats.items as Array<{
    id: string;
    seatNo: string;
    x: number;
    y: number;
    employeeName?: string;
  }>;
};

/**
 * 좌석 위치를 원래대로 되돌린다. 배치 편집 검증은 서버 상태를 실제로 바꾸므로,
 * 되돌리지 않으면 반복 실행할수록 좌석이 밀려 다음 실행이 깨진다.
 */
export const restoreSeat = async (
  page: Page,
  id: string,
  at: { x: number; y: number },
) => {
  const me = await (await page.request.get("/api/v1/auth/me")).json();
  await page.request.patch(`/api/v1/seats/${id}`, {
    headers: { "X-CSRF-Token": me.csrfToken },
    data: { x: at.x, y: at.y },
  });
};

/** 로그인한 세션의 CSRF 토큰. 변경 요청에 필요하다. */
export const csrfToken = async (page: Page) =>
  (await (await page.request.get("/api/v1/auth/me")).json())
    .csrfToken as string;

export const employeeId = async (page: Page, name: string) => {
  const found = await (
    await page.request.get(`/api/v1/employees?q=${encodeURIComponent(name)}`)
  ).json();
  return found.items[0].id as string;
};

/**
 * 직원의 좌석을 건드리는 검증을 감싼다.
 *
 * 배정을 바꾸는 검증이 원래대로 돌려놓지 않으면, 다음 검증이 "누가 어디 앉아
 * 있다"는 전제 위에서 엉뚱한 이유로 깨진다. 실제로 한 검증이 옮겨 놓은 직원
 * 때문에 다른 세 검증이 무너졌다.
 */
export const keepingSeats = async (
  page: Page,
  names: string[],
  body: () => Promise<void>,
) => {
  const before = await fetchSeats(page);
  const home = new Map(
    names.map((name) => [
      name,
      before.find((seat) => seat.employeeName === name)?.id ?? null,
    ]),
  );
  try {
    await body();
  } finally {
    const token = await csrfToken(page);
    const after = await fetchSeats(page);
    for (const [name, seatId] of home) {
      const now = after.find((seat) => seat.employeeName === name);
      if (now?.id === seatId) continue;
      if (now) {
        await page.request.delete(`/api/v1/seat-assignments/${now.id}`, {
          headers: { "X-CSRF-Token": token },
        });
      }
      if (seatId) {
        await page.request.post("/api/v1/seat-assignments", {
          headers: { "X-CSRF-Token": token },
          data: {
            employeeId: await employeeId(page, name),
            seatId,
            source: "manual",
            reason: "검증 정리",
          },
        });
      }
    }
  }
};

/**
 * 브라우저 콘솔 오류를 모은다. 타입 검사와 단위 테스트로는 드러나지 않는
 * 런타임 오류를 화면마다 붙잡는 용도다.
 */
export const watchConsole = (page: Page) => {
  const problems: string[] = [];
  page.on("console", (message) => {
    if (message.type() === "error") problems.push(message.text());
  });
  page.on("pageerror", (error) => problems.push(String(error)));
  return () => problems.filter((p) => !p.includes("401"));
};

export const expectNoConsoleErrors = async (page: Page, path: string) => {
  const problems = watchConsole(page);
  await page.goto(path);
  await expect(page.locator("main, [role=main]").first()).toBeVisible();
  expect(problems()).toHaveLength(0);
};
